<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
  }
  #game-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
  #snake {
    border: 2px solid #4a4a6a;
    border-radius: 4px;
    background: #0f0f1a;
    display: block;
  }
  #score {
    font-size: 24px;
    font-weight: bold;
    color: #7fff7f;
    text-shadow: 0 0 8px rgba(127,255,127,0.4);
    min-height: 30px;
  }
  #buttons {
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 24px;
    font-size: 16px;
    font-weight: 600;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: transform 0.1s, box-shadow 0.1s;
  }
  button:active { transform: scale(0.96); }
  #start {
    background: #2ecc71;
    color: #1a1a2e;
    box-shadow: 0 0 10px rgba(46,204,113,0.3);
  }
  #pause {
    background: #f39c12;
    color: #1a1a2e;
    box-shadow: 0 0 10px rgba(243,156,18,0.3);
  }
  #reset {
    background: #e74c3c;
    color: #fff;
    box-shadow: 0 0 10px rgba(231,76,60,0.3);
  }
</style>
</head>
<body>
<div id="game-container">
  <canvas id="snake" width="400" height="400"></canvas>
  <div id="score">Score: 0</div>
  <div id="buttons">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
</div>
<script>
(function() {
  const CELL = 20;
  const W = 20;  // cells wide
  const H = 20;  // cells tall
  const SPEED = 120; // ms per tick

  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const startBtn = document.getElementById('start');
  const pauseBtn = document.getElementById('pause');
  const resetBtn = document.getElementById('reset');

  let snake = [];
  let food = [0, 0];
  let dir = 'right';
  let nextDir = null;
  let alive = false;
  let score = 0;
  let intervalId = null;

  function opposite(a, b) {
    if (a === 'up' && b === 'down') return true;
    if (a === 'down' && b === 'up') return true;
    if (a === 'left' && b === 'right') return true;
    if (a === 'right' && b === 'left') return true;
    return false;
  }

  function randomFreeCell() {
    const occupied = new Set(snake.map(s => s[0] + ',' + s[1]));
    const free = [];
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        if (!occupied.has(x + ',' + y)) free.push([x, y]);
      }
    }
    if (free.length === 0) return [0, 0];
    return free[Math.floor(Math.random() * free.length)];
  }

  function drawCell(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= W; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL, 0);
      ctx.lineTo(x * CELL, H * CELL);
      ctx.stroke();
    }
    for (let y = 0; y <= H; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL);
      ctx.lineTo(W * CELL, y * CELL);
      ctx.stroke();
    }

    // Draw snake
    for (let i = 0; i < snake.length; i++) {
      const ratio = 1 - (i / snake.length) * 0.5;
      const g = Math.round(180 * ratio + 75 * ratio);
      if (i === 0) {
        // Head: brighter
        ctx.fillStyle = '#7fff7f';
        ctx.shadowColor = 'rgba(127,255,127,0.6)';
        ctx.shadowBlur = 8;
      } else {
        ctx.fillStyle = `rgb(${Math.round(40 + 80 * ratio)}, ${g}, ${Math.round(40 + 40 * ratio)})`;
        ctx.shadowBlur = 0;
      }
      const pad = i === 0 ? 0 : 1;
      ctx.fillRect(snake[i][0] * CELL + pad, snake[i][1] * CELL + pad, CELL - pad * 2, CELL - pad * 2);
    }
    ctx.shadowBlur = 0;

    // Draw food
    ctx.fillStyle = '#ff6b6b';
    ctx.shadowColor = 'rgba(255,107,107,0.5)';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(food[0] * CELL + CELL / 2, food[1] * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Game over overlay
    if (!alive && snake.length > 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff4444';
      ctx.font = 'bold 32px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 10);
      ctx.font = '18px sans-serif';
      ctx.fillStyle = '#ccc';
      ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 20);
      ctx.textAlign = 'start';
    }

    scoreEl.textContent = 'Score: ' + score;
  }

  function tick() {
    if (!alive) return;

    // Apply queued direction (check against current dir, not queued)
    if (nextDir !== null && !opposite(nextDir, dir)) {
      dir = nextDir;
      nextDir = null;
    }

    const head = snake[0];
    let nx = head[0], ny = head[1];
    if (dir === 'up') ny--;
    else if (dir === 'down') ny++;
    else if (dir === 'left') nx--;
    else if (dir === 'right') nx++;

    // Wall collision
    if (nx < 0 || nx >= W || ny < 0 || ny >= H) {
      alive = false;
      draw();
      stopInterval();
      return;
    }

    // Self collision
    for (let i = 0; i < snake.length; i++) {
      if (snake[i][0] === nx && snake[i][1] === ny) {
        alive = false;
        draw();
        stopInterval();
        return;
      }
    }

    // Move snake
    snake.unshift([nx, ny]);

    // Check food
    if (nx === food[0] && ny === food[1]) {
      score++;
      food = randomFreeCell();
    } else {
      snake.pop();
    }

    draw();
  }

  function stopInterval() {
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  window.game = {
    get w() { return W; },
    get h() { return H; },

    reset() {
      stopInterval();
      snake = [];
      const cx = Math.floor(W / 2);
      const cy = Math.floor(H / 2);
      snake.push([cx, cy]);
      snake.push([cx - 1, cy]);
      snake.push([cx - 2, cy]);
      dir = 'right';
      nextDir = null;
      alive = true;
      score = 0;
      food = randomFreeCell();
      draw();
    },

    tick: tick,

    setDir(d) {
      // Queue direction; will be checked against current dir on next tick
      if (d !== 'up' && d !== 'down' && d !== 'left' && d !== 'right') return;
      // If currently moving opposite, ignore 180
      // But we store it — the actual check happens in tick()
      nextDir = d;
    },

    setFood(x, y) {
      food = [x, y];
      draw();
    },

    snake() {
      return snake.map(s => [s[0], s[1]]);
    },

    food() {
      return [food[0], food[1]];
    },

    alive() {
      return alive;
    },

    score() {
      return score;
    }
  };

  // Keyboard controls
  document.addEventListener('keydown', function(e) {
    switch (e.key) {
      case 'ArrowUp':    e.preventDefault(); window.game.setDir('up'); break;
      case 'ArrowDown':  e.preventDefault(); window.game.setDir('down'); break;
      case 'ArrowLeft':  e.preventDefault(); window.game.setDir('left'); break;
      case 'ArrowRight': e.preventDefault(); window.game.setDir('right'); break;
    }
  });

  // Button controls
  startBtn.addEventListener('click', function() {
    if (!window.game.alive()) return;
    if (intervalId !== null) return;
    intervalId = setInterval(tick, SPEED);
  });

  pauseBtn.addEventListener('click', function() {
    stopInterval();
  });

  resetBtn.addEventListener('click', function() {
    window.game.reset();
  });

  // Initialize
  window.game.reset();
})();
</script>
</body>
</html>
